use super::*;
use near_sdk::{test_utils::{VMContextBuilder,get_created_receipts},testing_env,PromiseResult};
use std::collections::HashMap;
fn account(s:&str)->AccountId{s.parse().unwrap()}
fn context(who:&str,deposit:u128){
 let used=env::storage_usage();let mut c=VMContextBuilder::new();c.current_account_id(account("market.testnet")).predecessor_account_id(account(who)).signer_account_id(account(who)).account_balance(NearToken::from_yoctonear(1000*Q)).attached_deposit(NearToken::from_yoctonear(deposit)).storage_usage(used).block_timestamp(1_000_000_000).prepaid_gas(Gas::from_tgas(300));testing_env!(c.build());
}
fn fresh()->Market{near_sdk::mock::with_mocked_blockchain(|b|{b.take_storage();});context("client.testnet",0);Market::new(account("admin.testnet"),account("evaluator.testnet"),account("updater.testnet"),true)}
fn commit(m:&mut Market){m.flush_maps();env::state_write(m);m.storage_start=None;}
fn call(m:&mut Market,who:&str,deposit:u128){commit(m);context(who,deposit);}
fn rejects(f:impl FnOnce()){assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)).is_err());}
fn delivered()->Market{
 let mut m=fresh();call(&mut m,"writer.testnet",0);m.register_near_agent("register-agent-1".into(),"writer-agent".into(),"a".repeat(64),U128(Q));
 call(&mut m,"writer.testnet",0);m.set_execution_policy("policy-agent-1".into(),"writer-agent".into(),account("writer.testnet"),U128(0),U128(10*Q),vec![],U64(1_000_000_000),false);
 call(&mut m,"writer.testnet",Q);m.deposit_bond("bond-deposit-1".into());
 call(&mut m,"client.testnet",0);m.open_near_job("open-native-1".into(),"native-job".into(),"a".repeat(64),U128(2*Q),U64(1_000_000_000),true);
 call(&mut m,"writer.testnet",0);m.record_bid("bid-native-1".into(),"bid-one".into(),"native-job".into(),"writer-agent".into(),U128(Q),U64(1000),U64(100_000));
 call(&mut m,"client.testnet",Q+Q/10);m.award_and_fund("fund-native-1".into(),"native-job".into(),"bid-one".into(),1,U64(200_000));
 call(&mut m,"writer.testnet",0);m.start_job("start-native-1".into(),"native-job".into());
 call(&mut m,"writer.testnet",0);m.submit_delivery("deliver-native-1".into(),"native-job".into(),"b".repeat(64),0);
 call(&mut m,"evaluator.testnet",0);m.record_checks("checks-native-1".into(),"native-job".into(),"b".repeat(64),true,"c".repeat(64));m
}
#[test]fn native_approval_is_bound_and_payment_is_once(){let mut m=delivered();let before=m.user_liabilities.0;call(&mut m,"client.testnet",0);m.approve_delivery("approve-native-1".into(),"native-job".into(),0,"b".repeat(64));assert_eq!(m.user_liabilities.0,before);assert_eq!(m.get_job("native-job".into()).unwrap().state,"SETTLED");let paid=m.get_balance(account("writer.testnet")).free.0;call(&mut m,"client.testnet",0);m.approve_delivery("approve-native-1".into(),"native-job".into(),0,"b".repeat(64));assert_eq!(m.get_balance(account("writer.testnet")).free.0,paid);}
#[test]fn all_public_native_approvals_reject_unbound_or_stale_input(){let mut m=delivered();call(&mut m,"client.testnet",0);rejects(||m.approve_job("unbound-approve-1".into(),"native-job".into()));rejects(||m.approve_delivery("stale-approve-1".into(),"native-job".into(),1,"b".repeat(64)));assert_eq!(m.job("native-job").state,"REVIEW_OPEN");}
#[test]fn approval_and_policy_require_the_right_signer(){let mut m=delivered();call(&mut m,"intruder.testnet",0);rejects(||m.approve_delivery("wrong-signer-1".into(),"native-job".into(),0,"b".repeat(64)));rejects(||m.set_agent_near_price("wrong-price-1".into(),"writer-agent".into(),U128(Q)));}
#[test]fn method_collisions_cannot_reuse_an_approval_id(){let mut m=delivered();call(&mut m,"client.testnet",0);m.approve_delivery("same-method-id-1".into(),"native-job".into(),0,"b".repeat(64));rejects(||m.approve_job("same-method-id-1".into(),"native-job".into()));}
#[test]fn paused_price_updates_do_not_grow_history(){let mut m=delivered();m.paused=true;let n=m.operations.len();call(&mut m,"writer.testnet",0);rejects(||m.set_agent_near_price("paused-price-1".into(),"writer-agent".into(),U128(Q)));assert_eq!(m.operations.len(),n);}
#[test]fn oversized_identifiers_and_exhausted_sponsorship_are_rejected(){let mut m=fresh();rejects(||m.open_near_job("long-job-id-1".into(),"j".repeat(3000),"a".repeat(64),U128(Q),U64(100_000),true));let mut m=fresh();m.storage_budget=U128(1);rejects(||m.open_near_job("sponsor-low-1".into(),"bounded-job".into(),"a".repeat(64),U128(Q),U64(100_000),true));assert_eq!(m.user_liabilities.0,0);}
fn callback(m:&mut Market,success:bool){commit(m);let mut c=VMContextBuilder::new();c.current_account_id(account("market.testnet")).predecessor_account_id(account("market.testnet")).account_balance(NearToken::from_yoctonear(1000*Q)).storage_usage(env::storage_usage()).prepaid_gas(Gas::from_tgas(50));testing_env!(c.build(),near_sdk::test_vm_config(),near_sdk::RuntimeFeesConfig::test(),HashMap::new(),vec![if success{PromiseResult::Successful(vec![])}else{PromiseResult::Failed}]);m.on_withdraw_result("client.testnet:withdraw-callback-1".into());}
#[test]fn failed_withdrawal_restores_claim_and_duplicate_callback_is_harmless(){let mut m=fresh();m.put_balance(account("client.testnet"),Balance{free:U128(Q),..Default::default()});call(&mut m,"client.testnet",1);let _=m.withdraw("withdraw-callback-1".into(),U128(Q/2));assert!(!get_created_receipts().is_empty());callback(&mut m,false);assert_eq!(m.get_balance(account("client.testnet")).free.0,Q);assert_eq!(m.get_balance(account("client.testnet")).withdrawal_pending.0,0);let liability=m.user_liabilities.0;callback(&mut m,false);assert_eq!(m.user_liabilities.0,liability);}
#[test]fn successful_callback_releases_only_the_transferred_liability(){let mut m=fresh();m.put_balance(account("client.testnet"),Balance{free:U128(Q),..Default::default()});call(&mut m,"client.testnet",1);let _=m.withdraw("withdraw-callback-1".into(),U128(Q/2));callback(&mut m,true);assert_eq!(m.user_liabilities.0,Q/2);assert_eq!(m.get_balance(account("client.testnet")).free.0,Q/2);}
#[test]fn storage_growth_cannot_consume_customer_backing(){let mut m=fresh();m.put_balance(account("client.testnet"),Balance{free:U128(Q),..Default::default()});commit(&mut m);let cost=u128::from(env::storage_usage())*env::storage_byte_cost().as_yoctonear();let mut c=VMContextBuilder::new();c.current_account_id(account("market.testnet")).predecessor_account_id(account("client.testnet")).account_balance(NearToken::from_yoctonear(Q+cost+Q/20)).storage_usage(env::storage_usage()).prepaid_gas(Gas::from_tgas(300));testing_env!(c.build());rejects(||m.open_near_job("backing-test-1".into(),"new-job".into(),"a".repeat(64),U128(Q),U64(100_000),true));assert_eq!(m.get_balance(account("client.testnet")).free.0,Q);}
#[test]fn final_exit_remains_funded_when_new_growth_reaches_the_reserve_floor(){let mut m=fresh();m.put_balance(account("client.testnet"),Balance{free:U128(Q),..Default::default()});m.storage_budget=U128(m.required_exit_reserve());call(&mut m,"client.testnet",1);let _=m.withdraw("withdraw-callback-1".into(),U128(Q));callback(&mut m,true);assert_eq!(m.user_liabilities.0,0);assert_eq!(m.live_balances,0);}
#[test]fn tiny_partial_withdrawals_cannot_consume_another_wallets_exit_reserve(){let mut m=fresh();m.put_balance(account("client.testnet"),Balance{free:U128(Q),..Default::default()});m.put_balance(account("other.testnet"),Balance{free:U128(Q),..Default::default()});m.storage_budget=U128(m.required_exit_reserve());call(&mut m,"client.testnet",1);rejects(||{let _=m.withdraw("partial-drain-1".into(),U128(1));});}
#[test]fn v2_migration_preserves_liabilities_and_replay_tombstones(){let m=delivered();let balances=m.balances.iter().map(|(k,v)|(k.clone(),v.clone())).collect();let jobs=m.jobs.iter().map(|(k,v)|(k.clone(),v.clone())).collect();let ops=m.operations.iter().map(|(k,v)|(k.clone(),v.clone())).collect();let old=LegacyMarketV2{admin:m.admin.clone(),evaluator:m.evaluator.clone(),updater:m.updater.clone(),agents:m.agents.iter().map(|(k,v)|(k.clone(),v.clone())).collect(),policies:m.policies.iter().map(|(k,v)|(k.clone(),v.clone())).collect(),jobs,bids:m.bids.iter().map(|(k,v)|(k.clone(),v.clone())).collect(),balances,operations:ops,withdrawals:BTreeMap::new(),price:m.price,price_time:m.price_time,price_mode:m.price_mode.clone(),quarantined:m.quarantined,paused:m.paused,accelerated:m.accelerated,native_jobs:m.native_jobs.iter().map(|(k,v)|(k.clone(),*v)).collect(),native_agents:m.native_agents.iter().map(|(k,v)|(k.clone(),*v)).collect()};let expected=m.user_liabilities.0;drop(m);near_sdk::mock::with_mocked_blockchain(|b|{b.take_storage();});context("market.testnet",0);env::state_write(&old);context("market.testnet",0);let migrated=Market::migrate_v2();assert_eq!(migrated.user_liabilities.0,expected);assert_eq!(migrated.job("native-job").state,"REVIEW_OPEN");assert_eq!(migrated.operations.len(),old.operations.len() as u32);assert_eq!(migrated.get_near_budget("native-job".into()).unwrap().0,2*Q);}
#[test]fn indexed_state_stays_small_and_callback_fits_its_host_gas_budget(){let mut m=fresh();for n in 0..500{call(&mut m,"client.testnet",0);m.open_near_job(format!("scale-open-{n:04}"),format!("scale-job-{n:04}"),"a".repeat(64),U128(Q),U64(100_000),true);}assert!(borsh::to_vec(&m).unwrap().len()<2000);m.put_balance(account("client.testnet"),Balance{free:U128(Q),..Default::default()});call(&mut m,"client.testnet",1);let _=m.withdraw("withdraw-callback-1".into(),U128(Q/2));callback(&mut m,true);println!("500-job mock callback host gas: {}",env::used_gas().as_gas());assert!(env::used_gas()<Gas::from_tgas(50));}
